import{_ as t,o,c as d,a2 as a}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Security real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/security-real-driver-testing.md","filePath":"concepts/security-real-driver-testing.md"}'),r={name:"concepts/security-real-driver-testing.md"};function i(s,e,c,n,l,h){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="security-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" tabindex="-1">Security real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT) <a class="header-anchor" href="#security-real-driver-testing-—-8-axis-×-4-provider-32-cell-grid-real-driver-env-gate-ssot" aria-label="Permalink to &quot;Security real-driver testing — 8 axis × 4 provider = 32 cell grid + real-driver env-gate (SSOT)&quot;">​</a></h1><p>kiwa&#39;s v1.37-1 security package (<code>@kiwa/security</code> v0.1.0) covers <strong>8 axes</strong> that model the security posture of a real production stack — CSP + rate limiting + authorization + WAF + threat modeling + secrets scanning + SBOM + advanced security headers. This concept doc is the SSOT for those 8 axes; the tutorials (76-78) and dogfood apps (v1.37-2/3/4) are the concrete implementations.</p><h2 id="the-8-axis-grid" tabindex="-1">The 8-axis grid <a class="header-anchor" href="#the-8-axis-grid" aria-label="Permalink to &quot;The 8-axis grid&quot;">​</a></h2><p>The 8 axes are cover-oriented — each one names a real-world failure surface every non-trivial production security stack hits within the first quarter.</p><table tabindex="0"><thead><tr><th>Axis</th><th>Real-world failure it catches</th><th>v0.1 API</th></tr></thead><tbody><tr><td>CSP</td><td>&quot;The <code>&#39;strict-dynamic&#39;</code> directive silently disabled the whole <code>script-src</code> policy because no nonce was present, so every inline script fired unblocked and the CSP header showed green&quot; (no build-time invariant, no strict-dynamic + nonce co-requirement)</td><td><code>buildCspHeader</code> / <code>validateNonce</code> / <code>toCspEvent</code></td></tr><tr><td>Rate limit</td><td>&quot;The distributed rate limiter reset the token bucket every time the Redis key expired mid-window because the leaky bucket implementation double-counted the drain step&quot; (no window contract, no distributed drift guard)</td><td><code>TokenBucket</code> / <code>LeakyBucket</code> / <code>SlidingWindow</code> / <code>DistributedRateLimiter</code> / <code>resolveClientId</code> / <code>toRateLimitEvent</code></td></tr><tr><td>Authorization</td><td>&quot;The <code>admin</code> role stopped inheriting <code>viewer</code> permissions after a role rename but nobody caught it until a support ticket asked why the audit UI was blank&quot; (no role-hierarchy cycle guard, no combined RBAC + ABAC evaluator)</td><td><code>createRbacPolicy</code> / <code>expandRoles</code> / <code>rbacAllows</code> / <code>evaluateAbac</code> / <code>evaluateCombined</code> / <code>toAuthorizationEvent</code></td></tr><tr><td>WAF</td><td>&quot;The custom WAF rule fired allow before the OWASP CRS default fired deny because the rule-precedence order was undefined, and a SQL injection made it past&quot; (no rule precedence contract, no false-positive suppression)</td><td><code>createWafPolicy</code> / <code>evaluateWaf</code> / <code>addCustomRule</code> / <code>suppressFalsePositive</code> / <code>OWASP_CRS_DEFAULT</code> / <code>toWafEvent</code></td></tr><tr><td>Threat model</td><td>&quot;The STRIDE scoring drifted after a data-flow rewrite because the boundary crossings were never re-detected and DREAD row exposure jumped from 25 to 40 without a review&quot; (no boundary-crossing detector, no PASTA stage coverage)</td><td><code>scoreStride</code> / <code>scoreDread</code> / <code>detectBoundaryCrossings</code> / <code>pastaCoverage</code> / <code>toThreatModelEvent</code></td></tr><tr><td>Secrets scan</td><td>&quot;The Gitleaks rule caught a 40-char base64 string that was actually a natural-language sentence because the regex fired but the entropy gate was off&quot; (no Shannon-entropy floor, no signature deduplication)</td><td><code>scanSecrets</code> / <code>DEFAULT_SIGNATURES</code> / <code>shannonEntropy</code> / <code>isRotationOverdue</code> / <code>markRotated</code> / <code>toSecretsEvent</code></td></tr><tr><td>SBOM</td><td>&quot;The SBOM said 0 vulnerable components but the OSV feed had a critical for <code>left-pad@1.3.0</code> because the version-range parser only handled exact matches, not <code>&lt; 2.0.0</code>&quot; (no OR-clause range parser, no advisory-feed join)</td><td><code>toCycloneDx</code> / <code>toSpdx</code> / <code>validateSbom</code> / <code>lookupAdvisories</code> / <code>versionInRange</code> / <code>evaluateLicense</code> / <code>DEFAULT_LICENSE_POLICY</code> / <code>toSbomEvent</code></td></tr><tr><td>Security headers</td><td>&quot;The <code>Strict-Transport-Security</code> preload flag was set without <code>includeSubDomains</code>, and the browser accepted the header but the preload list rejected the submission — the operator only found out after a manual audit&quot; (no HSTS preload invariant, no Permissions-Policy syntax check)</td><td><code>buildSecurityHeaders</code> / <code>validateSecurityHeaders</code> / <code>toSecurityHeadersEvent</code></td></tr></tbody></table><p>Each axis has 3 shapes — a mock-only path (fast inner loop, ms scale), a real-driver path (<code>KIWA_MODE=real</code> + real helmet / express-rate-limit / casbin / coraza, seconds scale), and a fidelity assertion that the two produce the same output. Tutorial 76 covers the CSP axis end-to-end (build → nonce → hash → strict-dynamic → trusted-types → report-only), tutorial 77 covers the authorization axis (RBAC + role hierarchy + ABAC combining + combined RBAC + ABAC), tutorial 78 covers the SBOM + secrets-scan axes (CycloneDX + SPDX + advisory + license + secret finding + rotation SLA).</p><h2 id="the-4-provider-×-8-axis-32-cell-grid" tabindex="-1">The 4-provider × 8-axis = 32 cell grid <a class="header-anchor" href="#the-4-provider-×-8-axis-32-cell-grid" aria-label="Permalink to &quot;The 4-provider × 8-axis = 32 cell grid&quot;">​</a></h2><p>Every provider covers every axis. The mock shapes are provider-neutral (the API surface is the same across helmet + express-rate-limit + casbin + coraza), the emitted event dialects are provider-specific (<code>helmet.csp.violation</code> vs. <code>coraza.csp.violation</code> vs. <code>casbin.authorization.decision</code> vs. <code>express-rate-limit.rate-limit.exceeded</code>), and the fidelity harness reports the coverage explicitly through <code>SECURITY_FIDELITY_GRID</code>.</p><table tabindex="0"><thead><tr><th>Provider</th><th>CSP</th><th>Rate limit</th><th>Authorization</th><th>WAF</th><th>Threat model</th><th>Secrets scan</th><th>SBOM</th><th>Security headers</th></tr></thead><tbody><tr><td>helmet</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>express-rate-limit</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>casbin</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr><tr><td>coraza</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td><td>implemented</td></tr></tbody></table><p>The v1.37 security grid is fully covered — every provider implements every axis because the semantics are runtime-agnostic. That is what makes cross-provider reuse (a policy that runs under helmet + express-rate-limit + casbin + coraza without change) even possible.</p><h3 id="why-the-security-grid-is-fully-covered" tabindex="-1">Why the security grid is fully covered <a class="header-anchor" href="#why-the-security-grid-is-fully-covered" aria-label="Permalink to &quot;Why the security grid is fully covered&quot;">​</a></h3><p>helmet + express-rate-limit + casbin + coraza converged on the same neutral events at the &quot;read a request header, decide an allow / deny, emit an audit event&quot; primitive — the &quot;security policy over an HTTP request&quot; shape is the same across all 4 providers, even though the wire encodings differ (Node middleware vs. Redis-backed limiter vs. policy-engine adapter vs. WAF rules engine). The <code>providerEventName(target, neutralEvent)</code> mapping table is the single point where the 4 dialects diverge; everything upstream stays neutral. The v1.37 fidelity grid at 32/32 = 100 % implemented reflects that convergence at the &quot;policy decision&quot; level.</p><h2 id="the-kiwa-mode-real-env-gate-contract" tabindex="-1">The <code>KIWA_MODE=real</code> env-gate contract <a class="header-anchor" href="#the-kiwa-mode-real-env-gate-contract" aria-label="Permalink to &quot;The `KIWA_MODE=real` env-gate contract&quot;">​</a></h2><p><code>skipUnlessReal(provider, env)</code> returns <code>{ skip: false, reason: &#39;KIWA_MODE=real + required env present — real driver&#39; }</code> when <code>env.KIWA_MODE === &#39;real&#39;</code> and the required env for that provider is set, and <code>{ skip: true, reason: &#39;KIWA_MODE!=real (got &quot;unset&quot;) — mock driver&#39; }</code> otherwise. A test that respects the contract combines the gate with a required-env presence check — the dogfood apps use this at each <code>describe.skipIf(gate.skip)</code> block.</p><p>Per-provider required-env mapping (<code>REAL_DRIVER_REQUIRED_KEYS</code>).</p><ul><li><strong>helmet</strong> → <code>KIWA_MODE</code> only (helmet is Node-in-process, no external service needed)</li><li><strong>express-rate-limit</strong> → <code>KIWA_MODE</code> + <code>KIWA_REDIS_URL</code> (real Redis-backed distributed rate limiter)</li><li><strong>casbin</strong> → <code>KIWA_MODE</code> + <code>KIWA_CASBIN_POLICY_PATH</code> (real casbin policy file on disk)</li><li><strong>coraza</strong> → <code>KIWA_MODE</code> + <code>KIWA_CORAZA_RULES_PATH</code> (real coraza / OWASP CRS rule file on disk)</li></ul><p>A test that respects the contract runs the mock path unconditionally and the real-driver path only when both <code>KIWA_MODE=real</code> and the required env are present. That means CI stays cheap by default (mock only, ms scale), the nightly job flips <code>KIWA_MODE=real</code> + the required <code>_URL</code> / <code>_PATH</code> envs, and the fidelity harness ties the two together.</p><p>Absent env means silently fall back to mock mode — the test still runs, the real-driver assertions get skipped. Absent <code>KIWA_MODE</code> means fall back to mock. An invalid <code>KIWA_MODE</code> value (anything other than <code>real</code>) also falls back to mock so a typo does not break tests.</p><h2 id="the-dogfood-app-new-pattern" tabindex="-1">The dogfood app new pattern <a class="header-anchor" href="#the-dogfood-app-new-pattern" aria-label="Permalink to &quot;The dogfood app new pattern&quot;">​</a></h2><p>The 3 dogfood apps (v1.37-2/3/4) each expose a <code>pnpm test</code> command that keeps the mock-only path green sub-second, and are wired for <code>pnpm test:real</code> follow-up phases when the required envs are present.</p><ul><li><code>examples/dogfood-security-csp-headers-app</code> — Next.js middleware + CSP nonce + strict-dynamic + trusted-types + security headers advanced + <code>pnpm test:real</code> that walks the CSP chain (build policy → attach nonce → strict-dynamic → trusted-types → report-only) against a real Next.js middleware runtime. 70 test.</li><li><code>examples/dogfood-security-rbac-abac-app</code> — casbin + RBAC + ABAC + policy engine + role hierarchy + <code>pnpm test:real</code> that walks the authorization flow (RBAC allow → ABAC evaluate → combined RBAC + ABAC) against a real casbin policy adapter. 86 test.</li><li><code>examples/dogfood-security-sbom-scanning-app</code> — Trivy + CycloneDX + SPDX + Gitleaks + OSV / NVD + license policy + <code>pnpm test:real</code> that walks the SBOM + secrets scan flow (emit CycloneDX / SPDX → advisory lookup → license gate → secret finding → rotation SLA) against real Trivy + Gitleaks + OSV-Scanner. 62 test.</li></ul><p>The pattern each new app follows.</p><ol><li>Keep the mock-only path (<code>pnpm test</code>) green — the fast inner loop stays sub-second.</li><li>Add a <code>pnpm test:e2e</code> command that spins the docker-compose stack (Next.js runtime + Redis + casbin adapter + Trivy scanner, subset per app) and walks the real security policy flow.</li><li>Add a <code>pnpm test:real</code> command that requires the axis-specific <code>_URL</code> / <code>_PATH</code> env(s) and routes through the real provider endpoint.</li><li>Run the same fidelity-harness assertions against the real driver; failure means &quot;the mock diverged from real provider behavior&quot; — the mock gets the fix.</li><li>Emit a <code>quality-report/fidelity-latest.md</code> + <code>.json</code> that the v1.29 3-layer defensive structure (release-invariants + docs-e2e + release-smoke) picks up on merge.</li></ol><h2 id="the-not-implemented-failure-mode" tabindex="-1">The <code>not-implemented</code> failure mode <a class="header-anchor" href="#the-not-implemented-failure-mode" aria-label="Permalink to &quot;The `not-implemented` failure mode&quot;">​</a></h2><p>If the fidelity harness has a <code>planned</code> cell, the corresponding tutorial + dogfood + snippet-validation-test trio does not exist yet. The 32-cell grid at v1.37 has 0 <code>planned</code> cells — every intended cell is <code>implemented</code>. When a future milestone adds a 9th axis (e.g., <code>zero-trust-mtls</code> or <code>content-integrity-signing</code>), it will start as <code>planned</code> for all 4 providers, then transition to <code>implemented</code> for the ones that cover it as the milestone lands its tutorial + dogfood + snippet test.</p><h2 id="how-this-ties-into-the-13-axis-release-gate" tabindex="-1">How this ties into the 13-axis release gate <a class="header-anchor" href="#how-this-ties-into-the-13-axis-release-gate" aria-label="Permalink to &quot;How this ties into the 13-axis release gate&quot;">​</a></h2><p>v1.37 does not add a 14th release-gate axis. The 8 security axes gate the security package&#39;s own tests (via <code>pnpm --filter @kiwa/security test</code>) but do not surface as a per-package <code>@kiwa/quality-metrics</code> axis. The reasoning — the fidelity harness is provider-shape-specific, and a package that does not export to helmet / express-rate-limit / casbin / coraza has nothing to assert on. When a future milestone adds a <code>security.fidelity</code> axis that describes &quot;which security providers this package&#39;s tests hit,&quot; it will slot into the 13-axis release gate as the 14th; v1.37 keeps the axis count at 13.</p><h2 id="ssot-boundaries" tabindex="-1">SSOT boundaries <a class="header-anchor" href="#ssot-boundaries" aria-label="Permalink to &quot;SSOT boundaries&quot;">​</a></h2><ul><li>The 8 security axes live in this doc. Tutorials 76-78 and the migration guide (v1.36 → v1.37) link back here for the axis SSOT.</li><li>The 4-provider × 8-axis grid is the harness&#39;s data structure. The <code>SECURITY_FIDELITY_GRID</code> constant in <code>packages/security/src/fidelity.ts</code> is the code SSOT — this doc&#39;s grid table is derived from that constant.</li><li>The <code>KIWA_MODE=real</code> env-gate contract is shared with the v1.22 real-driver testing tutorial (auth adapters + Keycloak), the v1.31 streaming real-driver concept doc, the v1.32 database real-driver concept doc, the v1.33 payment real-driver concept doc, the v1.34 frontend real-driver concept doc, the v1.35 observability real-driver concept doc, and the v1.36 search real-driver concept doc. All seven use the same <code>skipUnlessReal(env)</code> pattern; the security axes just add provider <code>_URL</code> + <code>_PATH</code> envs (<code>KIWA_REDIS_URL</code> / <code>KIWA_CASBIN_POLICY_PATH</code> / <code>KIWA_CORAZA_RULES_PATH</code>) instead of <code>_URL</code>-only envs.</li></ul>',29)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
